import json
with open('/app/resources/treasury_bulletin_1991_09.json', 'r') as f:
    data = json.load(f)

# Look for sections with 'saving' or tables
def find_saving(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'saving' in str(k).lower() or 'saving' in str(v).lower():
                print(f'{path}.{k}' if path else k, ':', str(v)[:200])
            find_saving(v, f'{path}.{k}' if path else k)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):  # First 5 only
            find_saving(item, f'{path}[{i}]')

find_saving(data)
