import json
with open('/app/resources/treasury_bulletin_1991_09.json', 'r') as f:
    data = json.load(f)

# Print structure to understand what's available
def print_structure(obj, indent=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                print("  " * indent + str(k))
                print_structure(v, indent + 1)
            else:
                print("  " * indent + f"{k}: {str(v)[:50]}")
    elif isinstance(obj, list):
        print("  " * indent + f"[list of {len(obj)} items]")
        if obj and isinstance(obj[0], dict):
            print_structure(obj[0], indent + 1)

print_structure(data)
